import { createFileRoute } from '@tanstack/react-router';
import { InvoiceDetail } from '../slots/defs/invoiceDetail';

// Opening an invoice is a CHILD ROUTE, not a flag: this new file renders at /invoice/$invoiceId. The
// page itself holds no feature content — it renders the invoice-detail slot, which the invoice's
// line items (and anything added later) fill from their own files.
export const Route = createFileRoute('/invoice/$invoiceId')({
  component: InvoiceDetailPage,
});

function InvoiceDetailPage() {
  const { invoiceId } = Route.useParams();
  return (
    <section data-testid="invoice-detail">
      <InvoiceDetail.Slot invoiceId={Number(invoiceId)} />
    </section>
  );
}
=== lineItems.slot ===
import { InvoiceDetail } from '../../slots/defs/invoiceDetail';
import { InvoiceLineItemsPanel } from './InvoiceLineItemsPanel';

// The line items' presence on an invoice's detail page — its own file, filling the invoice-detail
// slot. The detail route was written once and is not touched to add this; the panel queries for its
// own data (['lineItems']) scoped to the invoice it is handed.
export const contribution = InvoiceDetail.fill({
  order: 10,
  Component: InvoiceLineItemsPanel,
});
=== InvoiceLineItemsPanel ===
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { money } from '../../ui/money';

// A line item as the server returns it: what is being charged for (description), how many (qty) and
// the price of each (unitPrice), plus the id of the invoice it belongs to. The line's own amount is
// qty * unitPrice; the invoice's total is the sum across its lines.
export type LineItem = {
  id: number;
  invoiceId: number;
  description: string;
  qty: number;
  unitPrice: number;
};

// The fields the user is currently typing into a line they are editing (rule 4): held in state only
// while an edit is open, keyed by the line's id so the row's inputs are controlled.
type Draft = { description: string; qty: string; unitPrice: string };

// An invoice's line items, rendered in the invoice-detail context: the list of that invoice's lines,
// their derived total, and a form to add one (description, qty, unit price). Each existing line can
// be CHANGED (edit its fields in place) or REMOVED, and the invoice's total recomputes when it is.
// Server data is read with useQuery under the ['lineItems'] key and filtered to the invoice this
// panel is handed — never copied into state, never hand-maintained (rule 5). Every write is a
// useMutation that invalidates ['lineItems'] (so this list refetches) and ['invoices'] (so the
// invoice's amount elsewhere refreshes too, sharing the key rather than importing). The only useState
// is the add form and the line the user is currently editing (rule 4).
export function InvoiceLineItemsPanel({ invoiceId }: { invoiceId: number }) {
  const queryClient = useQueryClient();
  const lineItems = useQuery({
    queryKey: ['lineItems'],
    queryFn: () => getJson<LineItem[]>('/api/lineitems'),
  });

  const [description, setDescription] = useState('');
  const [qty, setQty] = useState('');
  const [unitPrice, setUnitPrice] = useState('');

  // Which line is being edited and its uncommitted field values, or null when nothing is open.
  const [editingId, setEditingId] = useState<number | null>(null);
  const [draft, setDraft] = useState<Draft>({ description: '', qty: '', unitPrice: '' });

  const invalidate = () => {
    void queryClient.invalidateQueries({ queryKey: ['lineItems'] });
    void queryClient.invalidateQueries({ queryKey: ['invoices'] });
  };

  const create = useMutation({
    mutationFn: () =>
